def maxScoreWords(words: list[str], letters: list[str], score: list[int]) -> int:
    from collections import Counter
    letter_counts = Counter(letters)
    def word_val(w):
        return sum(score[ord(ch) - 97] for ch in w)
    def dfs(idx, counts):
        if idx == len(words): return 0
        # Skip word
        res = dfs(idx + 1, counts)
        # Try taking word
        w = words[idx]
        w_counts = Counter(w)
        if all(counts[ch] >= w_counts[ch] for ch in w_counts):
            new_counts = Counter(counts)
            for ch in w_counts: new_counts[ch] -= w_counts[ch]
            res = max(res, word_val(w) + dfs(idx + 1, new_counts))
        return res
    return dfs(0, letter_counts)

